    "// pinch sends) zooms around the pointer; Shift+wheel or a sideways swipe pans.\n"
    "cv.addEventListener(\"wheel\", e => {\n"
    "  const zoom = e.ctrlKey || e.metaKey, pan = e.shiftKey || Math.abs(e.deltaX) > Math.abs(e.deltaY);\n"
    "  if (!zoom && !pan) return;\n"
    "  e.preventDefault();\n"
    "  const r = cv.getBoundingClientRect(), x = e.clientX - r.left, w = cv.clientWidth - LABEL - 8;\n"
    "  if (zoom) {\n"
    "    const t = view[0] + (x - LABEL) / w * (view[1] - view[0]);\n"
    "    const k = Math.exp(Math.sign(e.deltaY) * Math.min(Math.abs(e.deltaY), 50) * 0.006);   // wheel notch or pinch\n"
    "    view = [t - (t - view[0]) * k, t + (view[1] - t) * k];\n"
    "    if (view[1] - view[0] < 0.5) view = [t - .25, t + .25];\n"
    "  } else {\n"
    "    const dt = (e.deltaX || e.deltaY) / w * (view[1] - view[0]);\n"
    "    view = [view[0] + dt, view[1] + dt];\n"
    "  }\n"
    "  clamp(); draw();\n"
    "}, {passive: false});\n"
    "cv.addEventListener(\"dblclick\", () => { view = full.slice(); draw(); });\n"
    "window.addEventListener(\"resize\", size);\n"
    "matchMedia(\"(prefers-color-scheme: dark)\").addEventListener(\"change\", draw);\n"
    "size();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n";
